/* ===== Móc khóa Ball 3D (three.js nạp lười qua API.three()). Code dựng hình giống mockup đã duyệt (design: scratchpad b3d).
   KC.lib() trả về các hàm makeStrap/sceneStrap/sceneBall sau khi nạp three. Vòng vẽ bỏ qua khi phần tử không hiển thị. ===== */
const KCSTOP=new Set();
const KCRM=()=>!!(S.reduce||(window.matchMedia&&matchMedia('(prefers-reduced-motion: reduce)').matches));
const KC={L:null,async lib(){if(this.L)return this.L;const T=await API.three();this.L=kcBuild(T);return this.L}};
function kcBuild(THREE){

const MINT=0x6adcb7,CREAM=0xfbf8ea;
function noiseTex(){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');const d=x.createImageData(128,128);for(let i=0;i<d.data.length;i+=4){const v=Math.floor(Math.random()*256);d.data[i]=d.data[i+1]=d.data[i+2]=v;d.data[i+3]=255}x.putImageData(d,0,0);const t=new THREE.CanvasTexture(c);t.wrapS=t.wrapT=THREE.RepeatWrapping;t.magFilter=t.minFilter=THREE.NearestFilter;t.generateMipmaps=false;t.repeat.set(20,10);return t}
const FACE_IMG=new Image();
function faceTex(){const c=document.createElement('canvas');c.width=2048;c.height=1024;const t=new THREE.CanvasTexture(c);t.anisotropy=4;
 FACE_IMG.onload=()=>{const x=c.getContext('2d');const W=470;x.drawImage(FACE_IMG,1536-W/2,560-W/2,W,W);t.needsUpdate=true};
 FACE_IMG.src='data:image/webp;base64,';return t}
const NT=noiseTex(),FT=faceTex();

function dispAt(x,y,z){const g=(cx,cy,cz,a,k)=>a*Math.exp(-k*(1-(x*cx+y*cy+z*cz)));
 return 1+.05*Math.sin(3*x+1)*Math.cos(2.4*y)+.045*Math.sin(4*z+2*x)
  +g(-.75,-.45,.45,.16,5)+g(.8,-.25,.4,.13,5)+g(-.2,.85,.4,.10,6)+g(.55,.6,-.5,.09,5)+g(-.7,.2,-.6,.09,5)
  -g(0,-1,.25,.14,7)-g(.2,.1,-1,.08,4)}
function warp(geo){const p=geo.attributes.position;for(let i=0;i<p.count;i++){const x=p.getX(i),y=p.getY(i),z=p.getZ(i),l=Math.hypot(x,y,z),d=dispAt(x/l,y/l,z/l);p.setXYZ(i,x*d,y*d,z*d)}geo.computeVertexNormals();return geo}
function makeBall(){
 const g=new THREE.Group();
 const body=new THREE.Mesh(warp(new THREE.SphereGeometry(1,64,48)),new THREE.MeshLambertMaterial({color:0x4cc9a2}));g.add(body);
 const SH=32;
 for(let i=1;i<=SH;i++){const k=i/SH;const m=new THREE.MeshLambertMaterial({color:new THREE.Color(MINT).lerp(new THREE.Color(0x9ff0d2),k*.55).multiplyScalar(.95+.12*k),alphaMap:NT,alphaTest:.1+.62*k});
  const s=new THREE.Mesh(warp(new THREE.SphereGeometry(1+k*.3,56,40)),m);s.userData.k=k;g.add(s)}
 const face=new THREE.Mesh(warp(new THREE.SphereGeometry(1.38,72,56)),new THREE.MeshBasicMaterial({map:FT,transparent:true,depthWrite:false,depthTest:false}));face.renderOrder=20;face.rotation.y=Math.PI;g.add(face);
 // gai kem nằm quanh phía trên/sau
 const sp=[[-.9,.55,-.1,.25],[-.5,.9,-.12,.27],[0,1.04,-.1,.28],[.52,.9,-.1,.27],[.92,.52,-.08,.25]];
 sp.forEach(([x,y,z,r])=>{const m=new THREE.Mesh(new THREE.SphereGeometry(r,20,16),new THREE.MeshLambertMaterial({color:CREAM,emissive:0x5a5748}));const d=new THREE.Vector3(x,y,z).normalize();d.multiplyScalar(1.34*dispAt(d.x,d.y,d.z));m.position.copy(d);g.add(m)});
 // quai nhãn nhỏ phía dưới phải
 const tag=new THREE.Mesh(new THREE.BoxGeometry(.28,.5,.04),new THREE.MeshLambertMaterial({color:0x6fd6bb}));tag.position.set(.72,-.78,-.5);tag.rotation.z=.6;g.add(tag);
 // vòng gắn xích
 const loop=new THREE.Mesh(new THREE.TorusGeometry(.1,.035,8,16),new THREE.MeshLambertMaterial({color:0x6fd6bb}));loop.position.set(0,1.3,0);g.add(loop);
 return g}
function makeChain(n){const g=new THREE.Group();const m=new THREE.MeshStandardMaterial({color:0xe4e8ee,metalness:.6,roughness:.3});
 for(let i=0;i<n;i++){const b=new THREE.Mesh(new THREE.SphereGeometry(.075,12,10),m);b.position.y=-i*.15;g.add(b)}
 const cap=new THREE.Mesh(new THREE.BoxGeometry(.3,.16,.08),m);cap.position.y=.1;g.add(cap);return g}

function starShape(R,r){const sh=new THREE.Shape();for(let i=0;i<10;i++){const a=Math.PI/2+i*Math.PI/5,rad=i%2?r:R;const x=Math.cos(a)*rad,y=Math.sin(a)*rad;i?sh.lineTo(x,y):sh.moveTo(x,y)}sh.closePath();return sh}
function heartShape(){const sh=new THREE.Shape();sh.moveTo(0,-.32);sh.bezierCurveTo(-.5,.02,-.34,.4,0,.18);sh.bezierCurveTo(.34,.4,.5,.02,0,-.32);return sh}
function charm(shape,color,sc){const g=new THREE.Group();
 const geo=new THREE.ExtrudeGeometry(shape,{depth:.12,bevelEnabled:true,bevelSize:.04,bevelThickness:.05,bevelSegments:3,curveSegments:12});geo.center();
 const m=new THREE.Mesh(geo,new THREE.MeshStandardMaterial({color,roughness:.28,metalness:.15,emissive:color,emissiveIntensity:.18}));
 const ol=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:0x3a2a7a,side:THREE.BackSide}));ol.scale.setScalar(1.12);
 g.add(m,ol);g.scale.setScalar(sc);return g}
function sparkTex(){const c=document.createElement('canvas');c.width=c.height=64;const x=c.getContext('2d');x.fillStyle='#fff';x.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,r=i%2?5:30;x.lineTo(32+Math.cos(a)*r,32+Math.sin(a)*r)}x.closePath();x.fill();return new THREE.CanvasTexture(c)}
const SPT=sparkTex();
function makeCharms(nCh,size){const root=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(.17,.035,10,24),new THREE.MeshStandardMaterial({color:0xffd24a,metalness:.7,roughness:.25}));root.add(ring);
 const X=1.55*size,defs=[[-X,1.0,starShape(.34,.15),0xffd24a,.95],[X,1.2,heartShape(),0xff7fb5,.95]];
 const subs=defs.map(([x,len,sh,col,sc],i)=>{const sub=new THREE.Group();sub.position.set(x,0,.5);
  const chn=makeChain(Math.round(len/.11));chn.remove(chn.children[chn.children.length-1]);chn.children.forEach(b=>{b.scale.setScalar(.8)});sub.add(chn);
  const c=charm(sh,col,sc);c.position.y=-(Math.round(len/.11)*.11)-.18;c.position.z=0;sub.add(c);sub.userData.ph=i*1.7;root.add(sub);return sub});
 root.userData.subs=subs;return root}
function scene(el,o){
 const W=()=>el.clientWidth,H=()=>el.clientHeight;
 const r=new THREE.WebGLRenderer({antialias:true,alpha:true,preserveDrawingBuffer:!!o.keep});r.setPixelRatio(Math.min(devicePixelRatio,2));r.setSize(W(),H());el.prepend(r.domElement);
 const sc=new THREE.Scene();const cam=new THREE.PerspectiveCamera(30,W()/H(),.1,50);cam.position.set(0,o.camY||0,o.camZ||10);cam.lookAt(0,o.look||0,0);
 sc.add(new THREE.AmbientLight(0xffffff,.45));const l=new THREE.DirectionalLight(0xffffff,.42);l.position.set(3,4,6);sc.add(l);
 const pivot=new THREE.Group();pivot.position.y=o.pivotY;sc.add(pivot);
 const nCh=o.chain||8,ch=makeChain(nCh);pivot.add(ch);
 const ball=makeBall();ball.scale.set((o.size||1)*1.06,(o.size||1)*.96,(o.size||1));ball.position.y=-(nCh*.15)-(o.size||1)*1.3;pivot.add(ball);
 const charms=makeCharms(nCh,o.size||1);charms.position.y=-(nCh*.15)-.15;pivot.add(charms);
 const sparks=[];for(let i=0;i<7;i++){const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:SPT,color:[0xffffff,0xfff0a0,0xffc0e0][i%3],transparent:true,depthWrite:false}));sp.userData={a:Math.random()*6.28,r:1.7+Math.random()*1.2,y:-(nCh*.15)-1+Math.random()*1.6,s:.12+Math.random()*.18,sp:.8+Math.random()};sc.add(sp);sparks.push(sp)}
 const st={ang:0,vel:0,spin:0,drag:false,lx:0,idle:true};
 el.addEventListener('pointerdown',e=>{st.drag=true;st.lx=e.clientX;st.vel+=(Math.random()<.5?-1:1)*.04});
 addEventListener('pointerup',()=>st.drag=false);
 el.addEventListener('pointermove',e=>{if(!st.drag||!o.drag)return;const dx=e.clientX-st.lx;st.lx=e.clientX;ball.rotation.y+=dx*.012;st.vel+=dx*.0006});
 let t0=performance.now();
 function tick(t){const dt=Math.min(.033,(t-t0)/1000);t0=t;
  // con lắc: gia tốc = -k*ang -c*vel + gió nhẹ
  st.vel+=(-14*st.ang-.55*st.vel+Math.sin(t/900)*.5)*dt;st.ang+=st.vel*dt;
  pivot.rotation.z=st.ang;
  charms.userData.subs.forEach(sb=>{sb.rotation.z=-st.ang*.4+Math.sin(t/520+sb.userData.ph)*.18+st.vel*.08});
  sparks.forEach(sp=>{const u=sp.userData,k=(Math.sin(t/1000*u.sp+u.a)+1)/2;sp.position.set(Math.cos(u.a)*u.r*(o.size||1)*.9,pivot.position.y+u.y*(o.size||1)*.9,.8);sp.scale.setScalar(u.s*k*(o.size||1)*3);sp.material.opacity=k});
  if(!st.drag&&o.auto)ball.rotation.y+=dt*.5;
  if(!o.auto&&!st.drag)ball.rotation.y=Math.sin(t/1700)*.5;
  // lông lắc nhẹ theo gió
  ball.children.forEach(c=>{const k=c.userData.k;if(k)c.rotation.z=Math.sin(t/600+k*3)*.004*k+st.ang*.03*k});
  r.render(sc,cam);if(!o.stop)requestAnimationFrame(tick)}
 requestAnimationFrame(tick);
 return{st,ball,renderer:r,cam,resize(){r.setSize(W(),H());cam.aspect=W()/H();cam.updateProjectionMatrix()}}}

const MAT={pearl:new THREE.MeshStandardMaterial({color:0xf2fff9,roughness:.22,metalness:.1}),
 mauve:new THREE.MeshStandardMaterial({color:0x5fd8b4,roughness:.12,metalness:.1,transparent:true,opacity:.9,emissive:0x2a9c7a,emissiveIntensity:.25}),
 silver:new THREE.MeshStandardMaterial({color:0xd6efe8,roughness:.25,metalness:.75}),
 cream:new THREE.MeshStandardMaterial({color:0xcff7e6,roughness:.2,metalness:.15,emissive:0x3f8f78,emissiveIntensity:.28}),
 pink:new THREE.MeshStandardMaterial({color:0x8fe9cf,roughness:.12,metalness:.1,transparent:true,opacity:.95,emissive:0x35a98a,emissiveIntensity:.3}),
 cord:new THREE.MeshStandardMaterial({color:0xeafff6,roughness:.7}),
 accent:new THREE.MeshStandardMaterial({color:0xd6efe8,roughness:.25,metalness:.75})};
function setAccent(hex){MAT.cord.color.set(hex);MAT.accent.color.set(hex)}
const bead=(r,m,y,x=0)=>{const b=new THREE.Mesh(new THREE.SphereGeometry(r,20,16),m);b.position.set(x,y,0);return b};
function letterTex(ch){const c=document.createElement('canvas');c.width=c.height=128;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,128,128);x.fillStyle='#161616';x.font='900 96px system-ui,Arial,sans-serif';x.textAlign='center';x.textBaseline='middle';x.fillText(ch,64,70);return new THREE.CanvasTexture(c)}
function bowMesh(){const g=new THREE.Group();const lobe=(sx)=>{const sh=new THREE.Shape();sh.moveTo(0,0);sh.bezierCurveTo(.2*sx,.5,.95*sx,.62,.95*sx,.18);sh.bezierCurveTo(.95*sx,-.1,.7*sx,-.05,.55*sx,0);sh.bezierCurveTo(.7*sx,.05,.95*sx,.1,.95*sx,-.18);sh.bezierCurveTo(.95*sx,-.62,.2*sx,-.5,0,0);
  const geo=new THREE.ExtrudeGeometry(sh,{depth:.14,bevelEnabled:true,bevelSize:.05,bevelThickness:.06,bevelSegments:3,curveSegments:14});geo.translate(0,0,-.07);return new THREE.Mesh(geo,MAT.cream)};
 g.add(lobe(1),lobe(-1));const k=new THREE.Mesh(new THREE.SphereGeometry(.2,18,14),MAT.cream);k.scale.set(1,1.15,.9);g.add(k);g.add(bead(.08,MAT.pearl,0,0).translateZ(.18));return g}
function starBead(){const g=new THREE.Group();const sh=starShape(.52,.26);
 const geo=new THREE.ExtrudeGeometry(sh,{depth:.2,bevelEnabled:true,bevelSize:.05,bevelThickness:.06,bevelSegments:3});geo.center();
 g.add(new THREE.Mesh(geo,MAT.pink));const fr=new THREE.Mesh(geo,MAT.silver);fr.scale.set(1.2,1.2,.9);fr.material=MAT.silver.clone();fr.material.side=THREE.BackSide;g.add(fr);return g}
function spiralMesh(){const pts=[];for(let i=0;i<=60;i++){const a=i*.34,r=.04+i*.0055;pts.push(new THREE.Vector3(Math.cos(a)*r*1.5,Math.sin(a)*r*1.5,0))}
 return new THREE.Mesh(new THREE.TubeGeometry(new THREE.CatmullRomCurve3(pts),120,.028,8,false),MAT.silver)}

function noteShapes(kind){const out=[];
 const head=(cx,cy)=>{const h=new THREE.Shape();h.absellipse(cx,cy,.2,.14,0,Math.PI*2,false,.5);return h};
 const stem=(x,y0,y1)=>{const r=new THREE.Shape();r.moveTo(x,y0);r.lineTo(x+.07,y0);r.lineTo(x+.07,y1);r.lineTo(x,y1);r.closePath();return r};
 if(kind==='one'){out.push(head(0,-.45),stem(.13,-.4,.45));const f=new THREE.Shape();f.moveTo(.2,.45);f.bezierCurveTo(.2,.2,.6,.2,.52,-.15);f.bezierCurveTo(.5,.1,.32,.12,.2,.28);f.closePath();out.push(f)}
 else{out.push(head(-.28,-.45),head(.3,-.55),stem(-.15,-.4,.4),stem(.43,-.5,.3));const b=new THREE.Shape();b.moveTo(-.15,.4);b.lineTo(.5,.3);b.lineTo(.5,.1);b.lineTo(-.15,.2);b.closePath();out.push(b)}
 return out}
function noteMesh(kind,color,sc){const g=new THREE.Group();const geo=new THREE.ExtrudeGeometry(noteShapes(kind),{depth:.1,bevelEnabled:true,bevelSize:.035,bevelThickness:.04,bevelSegments:2,curveSegments:14});geo.center();
 const mat=new THREE.MeshStandardMaterial({color,roughness:.2,metalness:.12,emissive:color,emissiveIntensity:.18});
 g.add(new THREE.Mesh(geo,mat));const ol=new THREE.Mesh(geo,new THREE.MeshBasicMaterial({color:0x1f8a6c,side:THREE.BackSide}));ol.scale.setScalar(1.1);g.add(ol);g.scale.setScalar(sc);return g}
function makeStrap(){
 const root=new THREE.Group();
 // day deo trang + khoen
 const loop=new THREE.Mesh(new THREE.TorusGeometry(.55,.03,8,32),MAT.cord);loop.scale.set(.55,1,1);loop.position.y=.55;root.add(loop);
 const l2=new THREE.Mesh(new THREE.TorusGeometry(.5,.025,8,32),MAT.cord);l2.scale.set(.5,1,1);l2.position.set(.08,.55,0);root.add(l2);
 const clasp=new THREE.Mesh(new THREE.CylinderGeometry(.1,.07,.3,12),MAT.accent);clasp.position.y=-.05;root.add(clasp);
 const wire=new THREE.Mesh(new THREE.CylinderGeometry(.018,.018,5.5,6),MAT.silver);wire.position.y=-2.8;root.add(wire);
 // hat tren truc chinh
 const N1=noteMesh('one',0x6fe3c0,.9);N1.position.set(.18,-.75,0);const N2=noteMesh('two',0xe6fff6,.8);N2.position.set(-.15,-1.5,0);root.add(N1,N2);
 const bow=new THREE.Group();bow.position.set(0,-2.4,.05);root.add(bow);
 const cs=.46,gap=.52;bow.add(new THREE.Mesh(new THREE.CylinderGeometry(.014,.014,gap*6,6),MAT.silver).rotateZ(Math.PI/2));
 'CORTIS'.split('').forEach((ch,i)=>{const t=letterTex(ch);const mats=[0,1,2,3,4,5].map(f=>new THREE.MeshStandardMaterial({color:0xffffff,roughness:.3,map:(f===4||f===5)?t:null}));const cube=new THREE.Mesh(new THREE.BoxGeometry(cs,cs,cs),mats);cube.position.x=(i-2.5)*gap;bow.add(cube)});
 const N3=noteMesh('one',0xe6fff6,.85);N3.position.set(.18,-3.2,0);root.add(N3);
 const sb=starBead();sb.position.y=-4.05;sb.scale.setScalar(1.15);root.add(sb);
 const N4=noteMesh('two',0x6fe3c0,.75);N4.position.set(-.15,-4.95,0);root.add(N4);
 const hook=new THREE.Mesh(new THREE.TorusGeometry(.12,.03,8,16),MAT.silver);hook.position.y=-5.35;root.add(hook);
 const left=new THREE.Group(),right=new THREE.Group();root.add(left,right);
 // logo CORTIS
 const LG=new THREE.Group();LG.position.y=-5.45;root.add(LG);
 const lt=new THREE.TextureLoader().load('data:image/webp;base64,');
 const lw2=1.9,lh=lw2*309/300;
 const lm=new THREE.MeshStandardMaterial({map:lt,transparent:true,side:THREE.DoubleSide,roughness:.4,alphaTest:.05});
 const lp=new THREE.Mesh(new THREE.PlaneGeometry(lw2,lh),lm);lp.position.y=-.2-lh/2;LG.add(lp);
 const lr=new THREE.Mesh(new THREE.TorusGeometry(.1,.025,8,16),MAT.silver);lr.position.y=-.1;LG.add(lr);
 // Ball o duoi cung
 const bp=new THREE.Group();bp.position.y=-7.7;root.add(bp);
 const ball=makeBall();ball.scale.set(1.0*1.06,1.0*.96,1.0);ball.position.y=-1.4;bp.add(ball);
 return{root,left,right,bp,ball,sb,bow,LG,notes:[N1,N2,N3,N4]}}
function sceneStrap(el,o){
 const W=()=>el.clientWidth,H=()=>el.clientHeight;
 const r=new THREE.WebGLRenderer({antialias:true,alpha:true});r.setPixelRatio(Math.min(devicePixelRatio,2));r.setSize(W(),H());el.prepend(r.domElement);
 const sc=new THREE.Scene();const cam=new THREE.PerspectiveCamera(30,W()/H(),.1,80);cam.position.set(o.camX||0,o.camY||-3,o.camZ||19);cam.lookAt(o.camX||0,o.look??-3,0);
 sc.add(new THREE.AmbientLight(0xffffff,.55));const l=new THREE.DirectionalLight(0xffffff,.55);l.position.set(3,4,8);sc.add(l);
 const pivot=new THREE.Group();pivot.position.set(o.px||0,o.py||3.4,0);sc.add(pivot);
 const S=makeStrap();S.root.scale.setScalar(o.scale||1);pivot.add(S.root);
 const st={ang:0,vel:0,drag:false,lx:0,yaw:0};
 el.addEventListener('pointerdown',e=>{st.drag=true;st.lx=e.clientX;st.vel+=(Math.random()<.5?-1:1)*.05});
 addEventListener('pointerup',()=>st.drag=false);
 el.addEventListener('pointermove',e=>{if(!st.drag||!o.drag)return;const dx=e.clientX-st.lx;st.lx=e.clientX;st.yaw+=dx*.012;st.vel+=dx*.0006});
 let t0=performance.now();
 function tick(t){if(KCRM())t=0;const dt=KCRM()?0:Math.min(.033,(t-t0)/1000);t0=t;
  st.vel+=(-12*st.ang-.45*st.vel+Math.sin(t/950)*.45)*dt;st.ang+=st.vel*dt;
  pivot.rotation.z=st.ang;
  if(!st.drag)st.yaw+=dt*(o.auto?.5:0);
  S.root.rotation.y=Math.sin(t/2300)*.12;
  S.ball.rotation.y=st.yaw;
  S.left.rotation.z=-st.ang*.5+Math.sin(t/560)*.1;S.right.rotation.z=-st.ang*.6+Math.sin(t/470+1.3)*.12;
  S.bp.rotation.z=-st.ang*.45+Math.sin(t/700+.6)*.08+st.vel*.1;
  S.bow.rotation.z=Math.sin(t/800)*.05;S.bow.rotation.y=Math.sin(t/1300)*.35;S.notes.forEach((n,i)=>{n.rotation.z=Math.sin(t/620+i*1.4)*.22;n.rotation.y=Math.sin(t/1100+i)*.5});S.LG.rotation.z=-st.ang*.3+Math.sin(t/640+.9)*.07;S.LG.rotation.y=Math.sin(t/1400)*.5;S.sb.rotation.y=Math.sin(t/900)*.6;
  S.ball.children.forEach(c=>{const k=c.userData.k;if(k)c.rotation.z=Math.sin(t/600+k*3)*.004*k});
  if(el.isConnected&&el.offsetParent!==null&&!document.hidden)r.render(sc,cam);if(!KCSTOP.has(el))requestAnimationFrame(tick)}
 requestAnimationFrame(tick);
 return{st,pivot,S,ball:S.ball,renderer:r,cam,group:pivot,resize(){r.setSize(W(),H());cam.aspect=W()/H();cam.updateProjectionMatrix()}}}

function sceneBall(el){
 const W=()=>el.clientWidth,H=()=>el.clientHeight;
 const r=new THREE.WebGLRenderer({antialias:true,alpha:true});r.setPixelRatio(Math.min(devicePixelRatio,2));r.setSize(W(),H());el.prepend(r.domElement);
 const sc=new THREE.Scene();const cam=new THREE.PerspectiveCamera(30,W()/H(),.1,50);cam.position.set(0,.05,7.3);cam.lookAt(0,0,0);
 sc.add(new THREE.AmbientLight(0xffffff,.55));const l=new THREE.DirectionalLight(0xffffff,.55);l.position.set(3,4,8);sc.add(l);
 const ball=makeBall();ball.scale.set(1.06,.96,1);sc.add(ball);
 function tick(t){ball.rotation.y=Math.sin(t/1400)*.6;ball.rotation.x=Math.sin(t/1900)*.08;ball.position.y=Math.sin(t/900)*.05;r.render(sc,cam);requestAnimationFrame(tick)}
 requestAnimationFrame(tick);
 return{resize(){r.setSize(W(),H());cam.aspect=W()/H();cam.updateProjectionMatrix()}}}


return {makeStrap,sceneStrap,sceneBall,setAccent}}
